 font-size: 16px;
 text-align: center;
 color: black;
 background-color: gray;
}
.english{
 text-align: center;
 background-color: #ffe4f4;
 border-radius: .3em;
 padding: 1em;
}
.translate{
 text-align: center;
 background-color: #edffc4;
 border-radius: .3em;
 padding: 1em;
}

.voice img{
 margin-left:5px;
 width: 1000px;
 height: 400px;
}

